class DeapNativeSolverIsolate {
  final SendPort _sendPort;
  DeapNativeSolverIsolate(this._sendPort);

  Future<Uint8List> evaluateRequest(Uint8List requestPayload) async {
    if (requestPayload.lengthInBytes > kMaxFfiPayloadBytes) throw ArgumentError('FFI payload > 16 MiB');
    final ReceivePort responsePort = ReceivePort();
    try {
      _sendPort.send(<Object>[requestPayload, responsePort.sendPort]);
      final Object? raw = await responsePort.first.timeout(const Duration(milliseconds: 500),
        onTimeout: () => throw TimeoutException('Solver isolate timeout (500ms)'));
      if (raw is Uint8List) return raw;
      throw StateError('Unexpected solver isolate response');
    } finally {
      responsePort.close();
    }
  }

  Future<Map<String, dynamic>> solveJson(String solverExecutablePath, Map<String, dynamic> requestJson) async {
    final String encodedRequest = jsonEncode(requestJson);
    final ProcessResult result = await Process.run(solverExecutablePath, <String>['--solve-json', encodedRequest])
      .timeout(const Duration(milliseconds: 500), onTimeout: () => throw TimeoutException('Solver timeout (500ms)'));
    if (result.exitCode != 0) throw StateError('Solver exited (${result.exitCode}): ${result.stderr}');
    final Object? decoded = jsonDecode(result.stdout.toString());
    if (decoded is Map<String, dynamic>) return decoded;
    throw StateError('Invalid solver JSON output');
  }
}
